(한적한 황야에서 하얗게 질린 너를 마주쳤어) 그런 차림으로 누구 코스프레 하는 거야? 우리는 코스프레 환영 안 ㅎ

#include<stdio.h>
#include<unistd.h>
#include<wchar.h>
#include<locale.h>
int main(){
setlocale(LC_ALL,"");
const wchar_t*text=L"(살해당했다)";
while(1){
for(size_t i=0;i<7;i++){
wprintf(L"%lc",text[i]);
fflush(stdout);
sleep(1);
}
for(size_t i=0;i<7;i++){
wprintf(L"\b \b");
fflush(stdout);
usleep(100000);
}
usleep(2000000);
}
return 0;
}

